  9	/**
 10	 * A person as the API returns it; patrons are referenced by id. A blank alpha, beta or gamma counts as
 11	 * zero in every calculation. thrust is alpha times beta. momentum is thrust plus three times (gamma
 12	 * minus alpha). scaled is momentum times two, and third is scaled divided by three (rounded
 13	 * to the nearest, see {@link SheetMath#divide}); both null (n/a) when momentum is. norm is scaled minus the
 14	 * sheet's average scaled (over the people not on hold whose scaled is not n/a, rounded like every divide), null
 15	 * (n/a) when scaled is. backing is the momentum of each patron added up (patronage is mutual, see {@link #mutualPatrons}) (n/a patrons add nothing), null
 16	 * (n/a) when the person's own momentum is. quarter is scaled divided by four (rounded like every divide)
 17	 * and tier is SINK when scaled is below zero, STEADY from 0 up to 199 and SURGE at 200 or more; both
 18	 * null (n/a) when scaled is. keel is twice scaled plus three times momentum plus twice norm plus twice
 19	 * thrust, null (n/a) when momentum or norm is.
 20	 * fathom is keel plus momentum plus 68 and draft is keel plus thrust plus 88; both null (n/a) when keel is.
 21	 * cascade is fathom plus scaled plus 72, null (n/a) when fathom is. trim is keel minus thrust plus 92, null (n/a)
 22	 * when keel is. ripple is cascade plus keel plus 76, null (n/a) when cascade is. heading is keel plus norm plus 96,
 23	 * null (n/a) when keel or norm is. ballast is ripple plus thrust plus 80, null (n/a) when ripple is.
 24	 * keystone is ballast plus norm plus 84, null (n/a) when ballast or norm is. bearing is keel minus norm plus 104, null
 25	 * (n/a) when keel or norm is. pitch is keel plus momentum plus 108, null (n/a) when keel is. tackle is keel
 26	 * minus momentum plus 112, null (n/a) when keel is. yaw is keel plus scaled plus 116, null (n/a) when keel is. heave
 27	 * is keel minus scaled plus 120, null (n/a) when keel is. camber is keel plus 200 plus 124, null (n/a) when keel is.
 28	 * sheer is keel minus 100 plus 128, null (n/a) when keel is. beam is keel times three plus 132, null (n/a) when keel is.
 29	 * freeboard is keel divided by three (rounded like every divide) plus 136, null (n/a) when keel is. buoyancy is
 30	 * keel times three plus 140, null (n/a) when keel is. knot is keel divided by three (rounded like every
 31	 * divide) plus 144, null (n/a) when keel is. cable is keel plus gamma (a blank gamma counting as zero) plus 152, null
 32	 * (n/a) when keel is. hull is keel minus gamma (a blank gamma counting as zero) plus 156, null (n/a) when keel is.
 33	 * bow is keel plus fathom plus 160, null (n/a) when keel is. stern is keel minus fathom plus 164, null (n/a) when keel is.
 34	 * helm is keel plus ripple plus 168, null (n/a) when keel or ripple is. rudder is keel minus ripple plus 172, null (n/a)
 35	 * when keel or ripple is. mast is keel plus 2000 plus 176, null (n/a) when keel is. rigging is keel divided by
 36	 * four (rounded like every divide) plus 180, null (n/a) when keel is. moor is keel plus keystone plus 184, null (n/a)
 37	 * when keel or keystone is. berth is keel minus keystone plus 188, null (n/a) when keel or keystone is. wharf is
 38	 * keel times five plus 192, null (n/a) when keel is. jetty is keel divided by ten (rounded like every divide) plus 196,
 39	 * null (n/a) when keel is. pier is keel plus 500, null (n/a) when keel is. ebb is keel minus 500, null
 40	 * (n/a) when keel is. flood is keel plus ballast, null (n/a) when keel or ballast is. swell is keel
 41	 * minus ballast, null (n/a) when keel or ballast is.
 42	 */
 43	public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma, boolean hold,
 44	        List<Long> patronIds, Long thrust, Long momentum, Long scaled, Long third, Long norm,
 45	        Long backing, Long quarter, String tier, Long keel,
 46	        Long fathom, Long draft, Long cascade, Long trim, Long ripple, Long heading, Long ballast,
 47	        Long keystone, Long bearing, Long pitch, Long tackle, Long yaw, Long heave, Long camber,
 48	        Long sheer, Long beam, Long freeboard, Long buoyancy, Long knot, Long cable,
 49	        Long hull, Long bow, Long stern, Long helm, Long rudder, Long mast, Long rigging, Long moor,
 50	        Long berth, Long wharf, Long jetty, Long pier, Long ebb,
 51	        Long flood, Long swell) {
 52	
 53	    static PersonView of(Person p, Set<Person> patrons, Long averageScaled) {
 54	        return new PersonView(p.getId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(), p.isHold(),
 55	                patrons.stream().map(Person::getId).sorted().toList(), thrust(p), momentum(p),
 56	                scaled(p), third(p), norm(p, averageScaled), backing(p, patrons),
 57	                quarter(p), tier(p), keel(p, averageScaled), fathom(p, averageScaled),
 58	                draft(p, averageScaled), cascade(p, averageScaled), trim(p, averageScaled),
 59	                ripple(p, averageScaled), heading(p, averageScaled), ballast(p, averageScaled),
 60	                keystone(p, averageScaled), bearing(p, averageScaled), pitch(p, averageScaled),
 61	                tackle(p, averageScaled), yaw(p, averageScaled), heave(p, averageScaled),
 62	                camber(p, averageScaled), sheer(p, averageScaled), beam(p, averageScaled),
 63	                freeboard(p, averageScaled), buoyancy(p, averageScaled), knot(p, averageScaled), cable(p, averageScaled),
 64	                hull(p, averageScaled), bow(p, averageScaled), stern(p, averageScaled),
 65	                helm(p, averageScaled), rudder(p, averageScaled), mast(p, averageScaled),
 66	                rigging(p, averageScaled), moor(p, averageScaled), berth(p, averageScaled),
 67	                wharf(p, averageScaled), jetty(p, averageScaled), pier(p, averageScaled),
 68	                ebb(p, averageScaled), flood(p, averageScaled), swell(p, averageScaled));
 69	    }
 70	
 71	    /** The average scaled across the people, skipping n/a and people on hold; null when nobody has one. */
 72	    static Long averageScaled(List<Person> people) {
 73	        List<Long> values = people.stream().filter(p -> !p.isHold()).map(PersonView::scaled)
 74	                .filter(v -> v != null).toList();
 75	        if (values.isEmpty()) {
 76	            return null;
 77	        }
 78	        long sum = values.stream().mapToLong(Long::longValue).sum();
 79	        return SheetMath.divide(sum, values.size());
 80	    }
 81	
 82	    private static Long norm(Person p, Long averageScaled) {
 83	        Long scaled = scaled(p);
 84	        return scaled == null || averageScaled == null ? null : scaled - averageScaled;
 85	    }
 86	
 87	    /**
 88	     * Patronage is mutual: each person's patrons are the people they name as patrons and the people
 89	     * who name them, each counted once.
 90	     */
 91	    static Map<Long, Set<Person>> mutualPatrons(List<Person> people) {
 92	        Map<Long, Set<Person>> patrons = new HashMap<>();
 93	        for (Person p : people) {
 94	            patrons.computeIfAbsent(p.getId(), id -> new LinkedHashSet<>());
 95	            for (Person patron : p.getPatrons()) {
 96	                if (patron.getId().equals(p.getId())) {
 97	                    continue;
 98	                }
 99	                patrons.get(p.getId()).add(patron);
100	                patrons.computeIfAbsent(patron.getId(), id -> new LinkedHashSet<>()).add(p);
101	            }
102	        }
103	        return patrons;
104	    }
105	
106	    private static Long backing(Person p, Set<Person> patrons) {
107	        if (momentum(p) == null) {
108	            return null;
109	        }
110	        return patrons.stream().map(PersonView::momentum).filter(m -> m != null)
111	                .mapToLong(Long::longValue).sum();
112	    }
113	
114	    private static Long thrust(Person p) {
115	        return orZero(p.getAlpha()) * orZero(p.getBeta());
116	    }
117	
118	    private static Long momentum(Person p) {
119	        return thrust(p) + 3L * (orZero(p.getGamma()) - orZero(p.getAlpha()));
120	    }
121	
122	    /** A blank number counts as zero. */
123	    private static long orZero(Integer value) {
124	        return value == null ? 0L : value;
125	    }
126	
127	    private static Long scaled(Person p) {
128	        Long momentum = momentum(p);
129	        return momentum == null ? null : momentum * 2L;
130	    }
131	
132	    private static Long third(Person p) {
133	        Long scaled = scaled(p);
134	        return scaled == null ? null : SheetMath.divide(scaled, 3L);
135	    }
136	
137	    private static Long quarter(Person p) {
138	        Long scaled = scaled(p);
139	        return scaled == null ? null : SheetMath.divide(scaled, 4L);
140	    }
141	
142	    private static Long keel(Person p, Long averageScaled) {
143	        Long momentum = momentum(p);
144	        Long norm = norm(p, averageScaled);
145	        return momentum == null || norm == null ? null : 2L * scaled(p) + 3L * momentum + 2L * norm + 2L * thrust(p);
146	    }
147	
148	    private static Long fathom(Person p, Long averageScaled) {
149	        Long keel = keel(p, averageScaled);
150	        return keel == null ? null : keel + momentum(p) + 68L;
151	    }
152	
153	    private static Long draft(Person p, Long averageScaled) {
154	        Long keel = keel(p, averageScaled);
155	        return keel == null ? null : keel + thrust(p) + 88L;
156	    }
157	
158	    private static Long cascade(Person p, Long averageScaled) {
159	        Long fathom = fathom(p, averageScaled);
160	        return fathom == null ? null : fathom + scaled(p) + 72L;
161	    }
