     5	export interface Person {
     6	  id: number;
     7	  name: string;
     8	  alpha: number | null;
     9	  beta: number | null;
    10	  gamma: number | null;
    11	  hold: boolean;
    12	  patronIds: number[];
    13	  // alpha times beta, a blank one counting as zero.
    14	  thrust: number | null;
